# Result: Chaotic genesis eyes nucleate within ordered towering columns — the stabilized portal nexus
#
# Interactive explorer with depth slider, zoom, pan, dynamic glow

import numpy as np
import matplotlib.pyplot as plt
from matplotlib.widgets import Slider

GOLDEN_RATIO = (1 + np.sqrt(5)) / 2
GOLDEN_ANGLE = np.radians(137.50776405003785)

# Enchanted Rock Eyes Codex — from enchanted_rock_eyes_universe.py
ENCHANTED_ROCK_CODEX = ""

# Devils Tower Columnar Codex — corrected verbatim transmission
DEVILS_TOWER_CODEX = ""

# Parse pulses correctly — only runs of 1s
ENCHANTED_PULSES = [len(run) for run in ENCHANTED_ROCK_CODEX.split('0') if run]
DEVILS_PULSES = [len(run) for run in DEVILS_TOWER_CODEX.split('0') if run]

def clamp_to_disk(z: complex) -> complex:
    r = abs(z)
    return z / r * 0.99 if r > 0.99 else z

def generate_fusion_universe(max_depth: int = 20) -> list[complex]:
    nodes = []
    
    # Switch point: Enchanted Rock chaos for early depths, Devils Tower order for late depths
    SWITCH_DEPTH = 11
    
    def recurse(current: complex, depth: int, er_idx: int, dt_idx: int):
        nodes.append(current)
        if depth >= max_depth:
            return
        
        if depth < SWITCH_DEPTH:
            pulses = ENCHANTED_PULSES
            idx = er_idx % len(pulses)
            pulse = pulses[idx]
        else:
            pulses = DEVILS_PULSES
            idx = dt_idx % len(pulses)
            pulse = pulses[idx]
        
        branches = 5 + (pulse % 6)
        if depth > max_depth - 5:
            branches += 10  # Late magnification for eyes within columns
        
        branches = max(4, min(25, branches))
        angle_offset = pulse * GOLDEN_ANGLE
        
        for i in range(branches):
            angle = i * (2 * np.pi / branches) + angle_offset
            offset = 0.58 * np.exp(1j * angle) * (GOLDEN_RATIO ** -depth)
            child = clamp_to_disk(current + offset)
            new_er_idx = er_idx + 1 if depth < SWITCH_DEPTH else er_idx
            new_dt_idx = dt_idx + 1 if depth >= SWITCH_DEPTH else dt_idx
            recurse(child, depth + 1, new_er_idx, new_dt_idx)
    
    recurse(0j, 0, 0, 0)
    return nodes

# Interactive Explorer
fig, ax = plt.subplots(figsize=(12, 12))
plt.subplots_adjust(bottom=0.15)
ax.set_facecolor('black')
fig.patch.set_facecolor('black')
ax.axis('off')
ax.set_aspect('equal')

disk_circle = plt.Circle((0, 0), 1, color='white', fill=False, lw=1.5, ls='--')
ax.add_patch(disk_circle)

ax_depth = plt.axes([0.15, 0.05, 0.7, 0.03], facecolor='gray')
slider_depth = Slider(ax_depth, 'Depth', 8, 24, valinit=18, valstep=1, color='cyan')

current_nodes = []

def update(val):
    depth = int(slider_depth.val)
    ax.clear()
    ax.set_facecolor('black')
    ax.axis('off')
    ax.set_aspect('equal')
    ax.add_patch(disk_circle)
    
    global current_nodes
    current_nodes = generate_fusion_universe(max_depth=depth)
    
    nodes_arr = np.array(current_nodes)
    x, y = nodes_arr.real, nodes_arr.imag
    
    r = np.abs(nodes_arr)
    sizes = 4 + 25 * (r / r.max())**2 if len(nodes_arr) > 1000 else 10
    alphas = 0.6 + 0.4 * (1 - r)
    
    ax.scatter(x, y, c='cyan', s=sizes, alpha=alphas, edgecolors='none')
    ax.set_xlim(-1.05, 1.05)
    ax.set_ylim(-1.05, 1.05)
    ax.set_title("Tower-Eyes Fusion Universe — Chaos Stabilized in Order", color='white', fontsize=16, pad=20)
    fig.canvas.draw_idle()

slider_depth.on_changed(update)

# Zoom + Pan (wheel and drag)
# ... [same as previous explorers — omitted for brevity, copy from devils_tower script]

update(18)
plt.show()
